    {

           using var activity =  StartCallActivity("SetStickerPositionInSetAsync", typeof(SetStickerPositionInSet).FullName ?? "SetStickerPositionInSetAsync");

           try
           {
             return client.SetStickerPositionInSetAsync(sticker, position);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
